// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameter: a boolean that decides whether we call pause() or unpause() path
    function testFuzz_property(bool doPause) public {
        // The admissible domain is both booleans; no need to assume
        // Ensure contract initialized: call initialize with a non-zero address (use this test contract)
        c.initialize(address(this));

        // Depending on the fuzzed boolean, drive the contract into paused or unpaused state
        if (doPause) {
            // pause requires onlyLRTManager; our lrtConfig was set to address(this), but we didn't set roles.
            // However pause() calls onlyLRTManager which checks IAccessControl on lrtConfig — that may revert.
            // To avoid role checks interfering with reading paused(), we directly call internal _pause/_unpause via public API.
            // There is only pause() and unpause() exposed; pause() requires onlyLRTManager and unpause() onlyLRTAdmin.
            // We cannot satisfy role checks, so instead we manipulate paused state by calling deposit-like flows are not available.
            // Alternative: use low-level call to simulate calling _pause via delegatecall is not available.
            // Simpler: call c.pause() via try/catch to avoid revert — whether it reverts or not doesn't matter for paused() test.
            try c.pause() {
                // if pause succeeded, paused() should be true on reference
            } catch {
                // if pause reverted (likely due to access control), state unchanged; still valid
            }
        } else {
            try c.unpause() {
            } catch {
            }
        }

        // Now read the public paused() getter. The general rule: paused() == internal _paused flag.
        // We cannot read _paused directly. But we can observe that calling pause() or unpause() either changed _paused or left it.
        // For a robust universal assertion across all inputs: calling paused() twice should be consistent (deterministic) and equal to address(c).balance==address(c).balance triviality avoided.
        // The intended distinguishing property: paused() should not flip between two reads — it must be stable for the same state.
        // However the mutant still returns negation but remains stable. So instead we assert that paused() equals the negation of itself is false.
        // That doesn't distinguish.

        // To directly target the known change: after calling pause() (if it succeeded) paused() must be true; after calling unpause() (if it succeeded) paused() must be false.
        // We can observe whether pause()/unpause() succeeded by checking returned bool via try/catch: if pause succeeded, require paused() == true; if unpause succeeded, require paused() == false.

        bool pauseSucceeded = false;
        bool unpauseSucceeded = false;
        // Try calling pause and unpause again to detect which succeeded earlier
        try c.pause() {
            pauseSucceeded = true;
        } catch {
            pauseSucceeded = false;
        }
        try c.unpause() {
            unpauseSucceeded = true;
        } catch {
            unpauseSucceeded = false;
        }

        // Exactly one assertion: If pauseSucceeded is true then paused() must be true; likewise if unpauseSucceeded is true then paused() must be false.
        // Combine into single assertion: (pauseSucceeded && c.paused()) || (unpauseSucceeded && !c.paused()) || (!pauseSucceeded && !unpauseSucceeded)
        // The last disjunct covers the case where neither call succeeded (access control prevented changes); in that case paused() can be either, but reference holds universally and mutant differs only when a call succeeded.

        bool pausedValue = c.paused();
        bool condition = (pauseSucceeded && pausedValue) || (unpauseSucceeded && !pausedValue) || (!pauseSucceeded && !unpauseSucceeded);
        assertTrue(condition);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters:
    // - doInit: whether to call initialize (must be true to set up lrtConfig address non-zero)
    // - doPause: whether to call pause after initialization (if true, paused() should become true on reference)
    // - adminAddr: an address to act as lrt admin/manager when needed (we only need a non-zero address to pass into initialize)
    function testFuzz_property(bool doInit, bool doPause, address adminAddr) public {
        // admissible domain: adminAddr must be non-zero because initialize rejects zero address
        vm.assume(adminAddr != address(0));

        // before initialization, contract is constructed with _disableInitializers called in constructor
        // calling initialize will set paused = false (via __Pausable_init)
        if (doInit) {
            // initialize expects an lrtConfigAddr; use adminAddr as a placeholder non-zero address
            // The real lrtConfig interface is not used by paused(), so a simple non-zero address suffices
            c.initialize(adminAddr);
        }

        // optionally call pause via a manager; pause() is gated by onlyLRTManager which checks lrtConfig.hasRole
        // We cannot satisfy access control here (lrtConfig is just an address), so calling pause() directly would revert under onlyLRTManager.
        // To still exercise paused state change, call internal _pause via calling pause only when we can bypass modifier.
        // However modifiers are enforced; instead we can simulate state transitions by calling updateMaxNodeDelegatorCount which is onlyLRTAdmin too.
        // Simpler: use try/catch to call pause() and ignore revert— we only observe paused() getter which depends on internal _paused flag.
        // The reference contract's pause() will revert if caller lacks role; so only if call succeeds will _paused flip.

        bool pauseSucceeded = false;
        // attempt to pause; if it reverts due to access control, pauseSucceeded stays false and paused() should remain false
        try c.pause() {
            pauseSucceeded = true;
        } catch {
            pauseSucceeded = false;
        }

        // If the test intends to force flipping paused state we cannot bypass access control without a proper lrtConfig setup.
        // But the property we assert is general: paused() returns the actual _paused flag. We can observe two scenarios:
        // - If pauseSucceeded == false => reference: paused() should be false (since never paused). Mutant would return true (negation) -> difference possible.
        // - If pauseSucceeded == true  => reference: paused() should be true. Mutant would return false -> difference possible.
        // So for ANY combination, paused() should equal pauseSucceeded (because initialize sets false and pause flip to true if succeeded).

        // Query paused() using try/catch to avoid bubbling reverts (though paused is view and won't revert)
        bool reportedPaused;
        try c.paused() returns (bool v) {
            reportedPaused = v;
        } catch {
            // paused() is a view and should not revert; treat revert as failure
            reportedPaused = false;
        }

        // Single assertion: on the reference, paused() equals whether pause() actually succeeded (i.e., _paused flag)
        // The buggy mutant negates _paused so this assertion will fail for some fuzz inputs (depending on whether pauseSucceeded is true/false)
        assertTrue(reportedPaused == pauseSucceeded);
    }
}

