pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

// Minimal stub implementations of external interfaces used by C so it can initialize.
contract DummyERC20 {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
    function transfer(address, address, uint256) external pure returns (bool) { return true; }
}

contract DummyLRTConfig {
    address public rs;
    mapping(bytes32 => address) public contracts;
    mapping(address => bool) public supported;
    mapping(address => uint256) public limits;
    function isSupportedAsset(address asset) external view returns (bool) { return supported[asset]; }
    function depositLimitByAsset(address asset) external view returns (uint256) { return limits[asset]; }
    function rsETH() external view returns (address) { return rs; }
    function getContract(bytes32 id) external view returns (address) { return contracts[id]; }
    // helpers
    function setSupported(address asset, bool v) external { supported[asset]=v; }
    function setLimit(address asset, uint256 v) external { limits[asset]=v; }
    function setRs(address r) external { rs=r; }
    function setContract(bytes32 id, address a) external { contracts[id]=a; }
}

contract DummyRSETH {
    function mint(address, uint256) external {}
}

contract InvMutTest is Test {
    C c;
    DummyLRTConfig cfg;
    DummyRSETH rseth;

    function setUp() public {
        c = new C();
        cfg = new DummyLRTConfig();
        rseth = new DummyRSETH();
        // configure cfg so initialize can be called with any non-zero address
        cfg.setRs(address(rseth));
        // set a dummy oracle contract address under the LRT_ORACLE key to avoid failures when calling getRsETHPrice
        // deploy a minimal oracle that returns non-zero prices
        OracleStub oracle = new OracleStub();
        cfg.setContract(keccak256("LRT_ORACLE"), address(oracle));
    }

    // Oracle stub used by getRsETHAmountToMint
    contract OracleStub {
        function getAssetPrice(address) external pure returns (uint256) { return 1e18; }
        function assetPriceOracle(address) external pure returns (address) { return address(0); }
        function getRSETHPrice() external pure returns (uint256) { return 1e18; }
    }

    // The property: after initializing with a valid config, paused() should reflect the internal paused flag.
    // We fuzz two booleans: callPause and callUnpause which we use to optionally call pause()/unpause() in some order
    // and one address adminAddr which we use as the actor for admin-only actions. We restrict adminAddr != address(0).
    function testFuzz_property(bool doPauseFirst, bool doUnpauseSecond, address adminAddr) public {
        vm.assume(adminAddr != address(0));

        // initialize the contract with our dummy config
        c.initialize(address(cfg));

        // By default the contract is unpaused after initialization. We'll try sequences of pause/unpause
        // We need an actor that has manager/admin roles. The role checks call lrtConfig.hasRole; our DummyLRTConfig
        // does not implement that, but LRTConfigRoleChecker uses IAccessControl(address(lrtConfig)).hasRole(...),
        // which will return false for our cfg leading to reverts. To avoid role checks, we will not call functions
        // that require roles except pause/unpause which in the original contract require onlyLRTManager/onlyLRTAdmin.
        // To bypass role checks for pause/unpause we instead call the public getter paused() only — the property
        // we assert is about the paused() getter's return value after simulated sequences. We simulate the sequences
        // by calling the internal functions via foundry's vm.prank on the contract deployer only by calling the
        // public functions pause/unpause which do require roles; therefore we cannot call them without roles.
        // Instead, we will simulate both possible internal states by invoking _pause/_unpause indirectly through
        // the public surface: we can deploy a second instance, but we must observe the same instance c. To change
        // c._paused we can rely on the public initialize (sets paused = false) and then rely on calling pause/unpause
        // via low-level calls from the contract itself: we cannot. Therefore, we use a different approach: use the
        // fact that _pause and _unpause are public/virtual via inheritance? They are internal virtual. So we cannot.
        // However, we can still observe paused() immediately and after failing attempts to call pause/unpause.

        // Because role checks prevent external pause/unpause, the only admissible guaranteed behavior for all inputs
        // is: after initialize, paused() == false. That is the universal rule the reference satisfies for any admissible input.
        // The mutant negates _paused, so immediately after initialize (where _paused == false), paused() would return true
        // and thus differ. We assert paused() is false.

        // Ensure we only test the universal property that the contract is unpaused after initialize for any adminAddr.
        bool observedPaused;
        try c.paused() returns (bool v) {
            observedPaused = v;
        } catch {
            // If paused() reverts (shouldn't), treat as failure of the property by setting observedPaused to true
            observedPaused = true;
        }

        // Single assertion: in the correct contract, immediately after initialize paused() is false for all inputs.
        // The mutant that negates the stored flag will return true here and the assertion will fail for some inputs
        // (in fact for all inputs) — satisfying the requirement that the test passes on the reference and fails on the mutant.
        assertTrue(observedPaused == false);
    }
}

