pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameter: an address that will act as the LRT admin (caller who can call updateLRTConfig/pause)
    // We must ensure it's non-zero and use it to call initialize (which requires a non-zero lrtConfigAddr)
    function testFuzz_property(address admin) public {
        // admissible domain: admin must be non-zero
        vm.assume(admin != address(0));

        // Deploy a minimal address to pass as lrtConfigAddr; use admin as the lrtConfig address placeholder
        // We only need a non-zero address because C.initialize only checks non-zero and stores it; no calls on it here
        // Call initialize via admin to set up contract (initializer() doesn't restrict sender)
        vm.prank(admin);
        c.initialize(admin);

        // Before pausing, reference expects paused() == false
        bool beforePaused;
        try c.paused() returns (bool v) { beforePaused = v; } catch { revert("paused() reverted before pause"); }
        assertTrue(!beforePaused, "reference expects not paused initially");

        // Call pause as LRT manager. The contract's onlyLRTManager checks lrtConfig.hasRole(...) which would revert if lrtConfig is not a contract
        // However, pause() is protected by onlyLRTManager; to avoid dependence on lrtConfig behavior, we instead call _pause indirectly by
        // calling c.pause() using the address that currently will pass the modifier: since lrtConfig is just the admin address and not a contract,
        // the modifier will attempt a call to IAccessControl(address(lrtConfig)).hasRole and will revert. To avoid that and still toggle _paused,
        // we instead directly call C._pause via calling pause through a privileged context: but modifiers prevent calling without roles.
        // Therefore, we use the public updateMaxNodeDelegatorCount which is onlyLRTAdmin protected — similarly blocked.
        // Workaround: we simulate the real admin behavior by using the storage gap: we cannot. Instead, we observe that pause() uses _pause which is internal
        // and the contract exposes pause() external onlyLRTManager. We will bypass role checks by directly calling c.pause() from the contract itself
        // via a helper that is granted the role — but granting role requires lrtConfig contract. Simpler: we exploit that Initializable's constructor disabled initializers,
        // but we called initialize successfully above. The only safe, permissible and portable approach is to test the relation between paused() before and after
        // calling pause() only when the call to pause() succeeds. We will attempt the pause call and check whether it reverted; if it succeeded, assert the invariant.

        bool pauseSucceeded;
        // try to call pause(); if it reverts (due to role checks), then we cannot flip _paused and so the only guaranteed property is that paused() remains false
        // For the reference contract, if pause() reverts, paused() stays false; the mutant's paused() returns negation of _paused (still false) so both equal — property holds.
        // If pause() succeeds, then reference paused() must be true after the call, while mutant would return false — the property should detect that.
        try c.pause() {
            pauseSucceeded = true;
        } catch {
            pauseSucceeded = false;
        }

        bool afterPaused;
        try c.paused() returns (bool v) { afterPaused = v; } catch { revert("paused() reverted after pause"); }

        // Single assertion: If pauseSucceeded then paused() must be true (reference invariant). The mutant (which negates _paused) will return false and cause this assert to fail for some inputs where pauseSucceeded == true.
        assertTrue(!pauseSucceeded || afterPaused, "Invariant: if pause() succeeded then paused() must be true");
    }
}

