pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // General rule: paused() accurately reflects the contract paused state.
    // Fuzzed parameter: a boolean decide whether to call pause() (by manager) or not.
    // We need actors with roles; but role checks consult lrtConfig which is uninitialized in C,
    // so onlyLRTManager and onlyLRTAdmin will revert if used. However pause()/unpause() require
    // onlyLRTManager/onlyLRTAdmin; to exercise paused state we can call _pause/_unpause only via
    // the public functions pause()/unpause. Since access control will revert, we instead rely on the
    // fact that the initial contract is unpaused; but to observe the difference we can directly
    // call paused() before and after calling pause() via try/catch expecting revert for mutant?
    // Better approach: paused() should return false initially; if we simulate a pause by calling
    // _pause via calling pause() — but access control blocks. So we instead assert that paused()
    // can be true after calling unpause() when contract is paused — to make it reachable, we exploit
    // that pause() and unpause() do not check lrtConfig at compile time; they rely on onlyLRTManager
    // / onlyLRTAdmin modifiers which will revert for both reference and mutant; thus we cannot call them.
    // Simpler universal property: paused() == false before any calls (initial state is unpaused). The mutant also returns false always, so that won't fail. To detect mutant we need a case where actual internal _paused is true but paused() returns false. We can cause internal _paused to become true by calling c.__Pausable_init() indirectly via initialize which sets unpaused, not paused.
    // Alternative: use updateLRTConfig to set lrtConfig and then call pause/unpause via roles. We'll deploy a dummy LRTConfig that grants MANAGER/ADMIN roles to our test actor.

    // Minimal helper: DummyLRTConfig implementing ILRTConfig and IAccessControl-like hasRole behavior.
    function testFuzz_property(bool doPause) public {
        // deploy a fake lrtConfig that treats this contract as configurable and grants roles to address(this)
        DummyLRTConfig lrt = new DummyLRTConfig(address(this));
        // initialize c with lrt config
        c.initialize(address(lrt));
        // when doPause == true, we will call pause() as manager (our test address has manager role)
        if (doPause) {
            // call pause as manager
            c.pause();
        }
        // Now read paused() via public getter. The reference implementation returns the internal _paused flag.
        // The mutant always returns false. So when doPause==true, reference returns true, mutant returns false.
        bool isPaused = c.paused();
        // exactly one assertion: when we requested a pause (doPause==true), paused() must be true
        // (this holds for the reference for all inputs) and the mutant will fail for doPause==true
        assertTrue(!doPause || isPaused);
    }
}

// Minimal dummy lrtConfig + access control to satisfy role checks and required getters
contract DummyLRTConfig {
    address public admin;
    mapping(bytes32 => address) public contracts;
    constructor(address admin_) {
        admin = admin_;
    }
    // simple role logic: MANAGER and DEFAULT_ADMIN_ROLE both map to admin
    function isSupportedAsset(address) external pure returns (bool) { return true; }
    function rsETH() external pure returns (address) { return address(0); }
    function assetStrategy(address) external pure returns (address) { return address(0); }
    function getLSTToken(bytes32) external pure returns (address) { return address(0); }
    function getContract(bytes32 contractId) external view returns (address) { return contracts[contractId]; }
    function getSupportedAssetList() external pure returns (address[] memory) { address[] memory a; return a; }
    function depositLimitByAsset(address) external pure returns (uint256) { return type(uint256).max; }
    // setters for C to call updateLRTConfig
    function setContract(bytes32 id, address addr) external { contracts[id] = addr; }

    // Access control imitation
    function hasRole(bytes32 role, address account) external view returns (bool) {
        // treat DEFAULT_ADMIN_ROLE (0x00) and MANAGER role as true for admin
        if (account == admin) return true;
        return false;
    }

    // required stub for LRT Oracle fetching
    function getContractAddress(bytes32) external view returns (address) { return address(0); }
}

