pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address admin = address(0xABCD);
    address manager = address(0xBEEF);

    function setUp() public {
        c = new C();
        // give admin and manager some ETH so they can be used with vm.prank if needed
        vm.deal(admin, 1 ether);
        vm.deal(manager, 1 ether);
    }

    // General rule: calling pause() by an address that has MANAGER role will set paused() to true on the reference.
    // The mutant always returns false, so there exist inputs (a manager caller) where paused() differs.
    function testFuzz_property(address caller) public {
        // admissible domain: caller must be non-zero
        vm.assume(caller != address(0));

        // We cannot actually grant roles in the imported contract (no access), but we can still test the observable
        // property that pause() toggles paused() when called by the manager role; to exercise pause(), we will
        // directly call pause() via vm.prank(caller). For the reference contract (correct), pause() will revert
        // unless caller has manager role; however the important universal property we assert is that if pause()
        // succeeds, then paused() must return true. The mutant always returns false, so for any caller that can
        // successfully call pause(), the mutant will fail this assertion.

        // Try calling pause(); capture whether it succeeded (did not revert).
        bool pauseSucceeded;
        try c.pause{gas: gasleft()}() {
            pauseSucceeded = true;
        } catch {
            pauseSucceeded = false;
        }

        // If pause succeeded on the deployed contract, then paused() MUST return true for the reference.
        // (This is the single assertion. The mutant will sometimes allow pause to succeed too but still return false.)
        if (pauseSucceeded) {
            bool isPaused = c.paused();
            assertTrue(isPaused);
        } else {
            // If pause did not succeed, we still must assert a general property that holds for all inputs.
            // In that case, paused() must be either true or false; to keep the universal property true for the
            // reference across all inputs while still letting the mutant fail on some, we assert that reading
            // paused() does not revert (i.e., call completes). We express that by calling it in try/catch and
            // asserting ok==true.
            bool ok;
            try c.paused() returns (bool) {
                ok = true;
            } catch {
                ok = false;
            }
            assertTrue(ok);
        }
    }
}

