pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

// Minimal stub implementations to satisfy interactions with ILRTConfig and access control.
contract DummyLRTConfig {
    mapping(bytes32 => address) public contracts;
    mapping(address => bool) public supported;
    function depositLimitByAsset(address) external pure returns (uint256) { return type(uint256).max; }
    function rsETH() external pure returns (address) { return address(0); }
    function getContract(bytes32 k) external view returns (address) { return contracts[k]; }
    function isSupportedAsset(address) external view returns (bool) { return supported[asset]; }
    address asset; // dummy to silence compiler - will be set in constructor
    constructor() { asset = address(0); }
}

// Minimal AccessControl mock: we implement hasRole so test can simulate MANAGER and ADMIN
contract SimpleAccessControl {
    mapping(bytes32 => mapping(address => bool)) public roles;
    function setRole(bytes32 role, address who, bool v) external { roles[role][who] = v; }
    function hasRole(bytes32 role, address account) external view returns (bool) {
        return roles[role][account];
    }
}

contract InvMutTest is Test {
    C c;
    SimpleAccessControl sac;

    function setUp() public {
        c = new C();
        sac = new SimpleAccessControl();
        // The contract C uses lrtConfig of type ILRTConfig; we cannot directly set it because C.updateLRTConfig requires onlyLRTAdmin.
        // But initialize requires an address; pass a dummy address and then call updateLRTConfig after granting admin role to this test address.
        // To satisfy initialize we deploy a dummy ILRTConfig-like contract that exposes required functions.
    }

    // We fuzz on an address that will act as the LRT admin (who can call updateLRTConfig) and another address that will act as the LRT manager (who can call pause).
    function testFuzz_property(address admin, address manager) public {
        // keep addresses non-zero and distinct and not the contract itself
        vm.assume(admin != address(0));
        vm.assume(manager != address(0));
        vm.assume(admin != address(this));
        vm.assume(manager != address(this));

        // We need a deployed ILRTConfig-compatible stub that C will call for isSupportedAsset/getContract/rsETH.
        // Deploy a minimal contract that implements the needed functions used by C.
        ILRTConfigStub lrt = new ILRTConfigStub();

        // initialize C with the stub's address
        c.initialize(address(lrt));

        // Now give the test harness the admin role in the LRTConfig stub so we can call updateLRTConfig on C.
        // The C.updateLRTConfig checks IAccessControl(address(lrtConfig)).hasRole(DEFAULT_ADMIN_ROLE, msg.sender)
        // Our ILRTConfigStub will forward hasRole to its internal SimpleAccessControl-like mapping; set admin role for address(this).
        lrt.setAdmin(address(this), true);

        // Now update LRTConfig pointer in c to point to our stub (though initialize already set it, we do this to follow patterns)
        c.updateLRTConfig(address(lrt));

        // Give manager role in the stub to the fuzzed manager address so manager can call pause()
        lrt.setManager(manager, true);

        // Precondition: contract must start unpaused. Reference implementation returns false initially; mutant also returns false.
        // Now simulate manager calling pause(). We will call pause() from the fuzzed manager address.
        vm.prank(manager);
        c.pause();

        // After pause() is called, the general rule is: for ANY manager address that successfully called pause(), c.paused() returns true.
        // We observe this by calling the public paused() getter. The reference C satisfies paused() == true here; the mutant returns false.
        bool ok;
        try c.paused() returns (bool val) {
            ok = val;
        } catch {
            ok = false; // in case paused() reverts (shouldn't)
        }

        // Single assertion: after a successful pause() call by a valid manager, c.paused() must be true.
        assertTrue(ok);
    }
}

// Minimal ILRTConfig-compatible stub used by the test. Implements only functions C calls.
contract ILRTConfigStub {
    mapping(address => bool) public managers;
    mapping(address => bool) public admins;

    function setManager(address who, bool v) external { managers[who] = v; }
    function setAdmin(address who, bool v) external { admins[who] = v; }

    // These are the functions C expects from ILRTConfig/IAccessControl
    function isSupportedAsset(address) external pure returns (bool) { return true; }
    function depositLimitByAsset(address) external pure returns (uint256) { return type(uint256).max; }
    function rsETH() external pure returns (address) { return address(0); }
    function getContract(bytes32) external view returns (address) { return address(this); }

    // Access control compatibility: hasRole used in LRTConfigRoleChecker
    function hasRole(bytes32 role, address account) external view returns (bool) {
        bytes32 MANAGER = 0x0; // not used
        // LRTConstants.MANAGER role will be checked by onlyLRTManager modifier via IAccessControl(address(lrtConfig)).hasRole(...)
        // We cannot distinguish roles here; instead we treat any call checking for MANAGER role by looking up managers mapping by account.
        // The LRTConfigRoleChecker uses different role constants; tests set managers/admins via setManager/setAdmin.
        return managers[account] || admins[account];
    }
}

