pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed parameter: an address that will act as LRT admin/manager depending on role checks in mocked environment.
    // We only need some address to call pause/unpause; the reference contract's paused() reflects internal _paused flag.
    // The mutant that always returns false will differ when the contract is actually paused.
    function testFuzz_property(address caller) public {
        // keep caller non-zero to be sensible
        vm.assume(caller != address(0));

        // We need to drive the contract into paused state. The contract's pause() requires onlyLRTManager role
        // which consults lrtConfig.hasRole. We cannot change lrtConfig here (it's zero address) but we can call _pause
        // only via calling pause(). However role checks will revert. To avoid role checks interfering, we will not call
        // pause(); instead we can simulate the paused state by calling internal _pause via using the public unpause/pause
        // not accessible. But we can observe difference by calling paused() before and after calling c._disableInitializers()
        // which doesn't change _paused. Therefore we instead rely on the public pause/unpause requiring roles which would
        // revert for arbitrary caller; to avoid reverts we will directly call c.paused() to read view — the reference
        // returns the real _paused state (initially false). To create a state where reference returns true, we can call
        // c.__Pausable_init() via a delegatecall? Not possible externally. Therefore we set up the scenario by deploying a
        // small harness that can call c.pause() while bypassing role checks by making lrtConfig return that caller has role.

        // Deploy a minimal mock LRTConfig that grants roles to any caller via IAccessControl interface methods used
        // by LRTConfigRoleChecker: hasRole. We'll implement only hasRole and other used getters.
        MockLRTConfig mock = new MockLRTConfig();
        // update c's lrtConfig via updateLRTConfig, which requires onlyLRTAdmin role — initially lrtConfig is zero and
        // onlyLRTAdmin checks IAccessControl.hasRole(DEFAULT_ADMIN_ROLE, msg.sender). Our mock will grant DEFAULT_ADMIN_ROLE
        // to address(this) so updateLRTConfig will succeed when called by this test contract. We call as this contract.
        c.updateLRTConfig(address(mock));

        // Now make this test contract have MANAGER role in mock and call pause(). mock will grant roles to this.
        mock.setGrantAllRolesTo(address(this));

        // Now call pause() to set the contract into paused state
        c.pause();

        // Now read paused() with try/catch to observe it does not revert and get boolean
        bool ok;
        try c.paused() returns (bool val) {
            ok = val;
        } catch {
            ok = false;
        }

        // The reference contract guarantees paused() returns the actual paused state; since we just called pause(),
        // the actual paused state is true. So assertTrue(ok) should hold for reference. The mutant that always returns
        // false will fail this assertion for some inputs (here for any caller) — fuzzing the caller is required by rules.
        assertTrue(ok);
    }
}

// Minimal mock implementing the bits of ILRTConfig/IAccessControl/ILRTOracle/IRSETH used by C and role checks.
contract MockLRTConfig {
    address public granted;
    mapping(bytes32 => address) public tokens;

    function setGrantAllRolesTo(address who) external {
        granted = who;
    }

    // IAccessControl.hasRole used by LRTConfigRoleChecker
    function hasRole(bytes32, address account) external view returns (bool) {
        return account == granted || account == msg.sender;
