contract DummyOracle {
    uint256 public price = 1e18;
    uint256 public rsethPrice = 1e18;
    function setPrices(uint256 p, uint256 r) external { price = p; rsethPrice = r; }
    function getAssetPrice(address) external view returns (uint256) { return price; }
    function assetPriceOracle(address) external view returns (address) { return address(0); }
    function getRSETHPrice() external view returns (uint256) { return rsethPrice; }
}

contract RSETHMock {
    mapping(address => uint256) public balanceOf;
    function mint(address account, uint256 amount) external { balanceOf[account] += amount; }
    function burn(address, uint256) external { }
}

// Minimal ERC20 used as asset
contract ERC20Mock {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    function mint(address to, uint256 amt) external { balanceOf[to] += amt; }
    function approve(address spender, uint256 amt) external returns (bool) { allowance[msg.sender][spender] = amt; return true; }
    function transferFrom(address from, address to, uint256 amt) external returns (bool) {
        if (balanceOf[from] < amt) return false;
        if (allowance[from][msg.sender] < amt) return false;
        allowance[from][msg.sender] -= amt;
        balanceOf[from] -= amt;
        balanceOf[to] += amt;
        return true;
    }
    function transfer(address to, uint256 amt) external returns (bool) {
        if (balanceOf[msg.sender] < amt) return false;
        balanceOf[msg.sender] -= amt;
        balanceOf[to] += amt;
        return true;
    }
}

contract InvMutTest is Test {
    C c;
    LRTConfigMock lrtConfig;
    DummyOracle oracle;
    RSETHMock rseth;
    ERC20Mock asset;

    // role constants from original code
    bytes32 constant MANAGER = 0x0;

    function setUp() public {
        c = new C();

        // deploy and configure mocks
        lrtConfig = new LRTConfigMock();
        oracle = new DummyOracle();
        rseth = new RSETHMock();
        asset = new ERC20Mock();

        lrtConfig.setOracle(address(oracle));
        lrtConfig.setRsETH(address(rseth));
        lrtConfig.setSupported(address(asset), true);
        lrtConfig.setLimit(address(asset), type(uint256).max);

        // initialize C with lrtConfig
        c.initialize(address(lrtConfig));

        // We cannot set access control roles via real AccessControl here; instead rely on the fact
        // that onlyLRTManager uses lrtConfig.hasRole on IAccessControl(address(lrtConfig)).hasRole(...)
        // Our LRTConfigMock does not implement hasRole; however onlyLRTManager calls IAccessControl(address(lrtConfig)).hasRole
        // To satisfy role checks, we will deploy a tiny wrapper that makes lrtConfig address appear to have roles by using
        // a helper that returns true for hasRole when queried for MANAGER by our test actor.
        // But since we cannot change c.lrtConfig to point to that wrapper now (already set), we instead avoid calling functions
        // that require manager role. We will call pause() via a direct low-level call from an address that the contract's onlyLRTManager
        // modifier will check against lrtConfig.hasRole. To ensure pause() succeeds, we will temporarily replace lrtConfig with an
        // address that responds true to hasRole for the MANAGER role. We'll deploy a HasRoleResponder and call updateLRTConfig.

        HasRoleResponder responder = new HasRoleResponder();
        responder.setManager(address(this));
        lrtConfig = LRTConfigMock(address(responder));
        // point c to new lrtConfig that supports role checking
        c.updateLRTConfig(address(responder));

        // also ensure the contract's supported asset and limits are set on this responder
        HasRoleResponder(address(responder)).setSupported(address(asset), true);
        HasRoleResponder(address(responder)).setLimit(address(asset), type(uint256).max);
        HasRoleResponder(address(responder)).setOracle(address(oracle));
        HasRoleResponder(address(responder)).setRsETH(address(rseth));
    }

    // fuzzed param: an address to act as caller when invoking pause()
    function testFuzz_property(address caller) public {
        // admissible domain: caller should be non-zero
        vm.assume(caller != address(0));

        // make caller the manager in the responder so pause() will succeed when called by that address
        HasRoleResponder responder = HasRoleResponder(c.lrtConfig());
        responder.setManager(caller);

        // the property: if pause() call succeeds (does not revert) when made by caller, then paused() must return true
        bool ok;
        // perform the call as caller
        vm.prank(caller);
        try c.pause() {
            ok = true;
        } catch {
            ok = false;
        }

        // If the call succeeded, the reference implementation guarantees paused() == true
        // We assert that: if ok then c.paused() must be true.
        if (ok) {
            bool reportedPaused = c.paused();
            assertTrue(reportedPaused);
        } else {
            // if call reverted, nothing to assert about paused state; still satisfy single-assert rule by asserting true
            // But we must have exactly one assertTrue overall; to comply, convert into an assertion that always holds when !ok
            // Use the contract's paused() as observation: when call failed, paused() should be false (reference property) is NOT guaranteed,
            // so instead we simply assertTrue(!ok || c.paused()); which still counts as a single assertion below.
            assertTrue(!ok || c.paused());
        }
    }
}

// Helper that responds to hasRole and exposes needed LRTConfig-like getters used by C
contract HasRoleResponder {
    address public manager;
    address public oracle;
    address public rseth;
    mapping(address => bool) public supported;
    mapping(address => uint256) public limits;

    function setManager(address m) external { manager = m; }
    function setOracle(address o) external { oracle = o; }
    function setRsETH(address r) external { rseth = r; }
    function setSupported(address a, bool s) external { supported[a] = s; }
    function setLimit(address a, uint256 l) external { limits[a] = l; }

    // mimic IAccessControl.hasRole: return true for MANAGER role when queried for our manager
    function hasRole(bytes32 role, address account) external view returns (bool) {
        // treat any role as manager role; check account
        return account == manager;
    }

    // LRTConfig getters used by C
    function rsETH() external view returns (address) { return rseth; }
    function assetStrategy(address) external view returns (address) { return address(0); }
    function isSupportedAsset(address asset) external view returns (bool) { return supported[asset]; }
    function getLSTToken(bytes32) external view returns (address) { return address(0); }
    function getContract(bytes32 contractId) external view returns (address) { return oracle; }
    function getSupportedAssetList() external view returns (address[] memory) { address[] memory a; return a; }
    function depositLimitByAsset(address asset) external view returns (uint256) { return limits[asset]; }
}

