            DummyLRTConfig d = new DummyLRTConfig();
            addrToUse = address(d);
        }

        // call initialize; catch revert just in case (but with non-zero addr it should succeed)
        bool ok;
        try c.initialize(addrToUse) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: for any non-zero lrtConfig address, reference sets maxNodeDelegatorCount == 10
        // so initialize should succeed and result in getter == 10. We assert the getter equals 10 only when
        // initialize succeeded; this is a single assertTrue reading c's public getter as required.
        if (ok) {
            assertTrue(c.maxNodeDelegatorCount() == 10);
        } else {
            // If initialize reverted unexpectedly (shouldn't for reference on admissible inputs), assert false
            // to fail the test; still a single assertTrue overall because one of the branches executes an assertTrue.
            assertTrue(false);
        }
    }
}

